mapper.select:
select
a.union_id,
a.rule_id,
a.union_name,
a.rule_delay,
a.robot_id,
a.mete_id,
a.triggering_time,
a.rule_name,
a.is_finish,
a.start_time,
a.create_time,
a.param_values,
a.plan_name,
a.rule_content
from t_union_task a
where 1 = 1
 and a.union_id = #{unionId, jdbcType=VARCHAR}
 and a.rule_id = #{ruleId, jdbcType=BIGINT}
 and a.union_name = #{unionName, jdbcType=VARCHAR}
 and a.rule_delay = #{ruleDelay, ruleDelay=INTEGER}
 and a.robot_id = #{robotId, jdbcType=BIGINT}
 and a.mete_id = #{meteId, jdbcType=BIGINT}
 and a.triggering_time = #{triggeringTime, jdbcType=TIMESTAMP}
 and a.rule_name = #{ruleName, jdbcType=VARCHAR}
 and a.is_finish = #{isFinish, jdbcType=INTEGER}
 and a.start_time = #{startTime, jdbcType=TIMESTAMP}
 and a.create_time = #{createTime, jdbcType=VARCHAR}
 and a.param_values = #{paramValues, jdbcType=TIMESTAMP}
 and a.plan_name = #{planName, jdbcType=VARCHAR}
 and a.rule_content = #{ruleContent, jdbcType=VARCHAR}

